entries[89197] = { ["name"] = "Scherwindkaktussamen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Pflanzt einen Scherwindkaktussamen.\nBenötigt einen respektvollen Ruf bei den Ackerbauern\n\"Der Scherwindkaktus ist mit Millionen feinster Nadeln bedeckt, die den vorbeiziehenden Wind filtern. Windwollfasern und Reste anderer Materialien bleiben häufig an ihnen hängen.\"\nVerkaufspreis:" }
entries[89202] = { ["name"] = "Raptorblattsamen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Pflanzt Raptorblattsamen.\nBenötigt einen respektvollen Ruf bei den Ackerbauern\n\"Das Raptorblatt ist eine fleischfressende Pflanze, der regelmäßig Shed-Ling, Falken und andere Kleintiere zum Opfer fallen. Nach einem einzigen Fang stirbt sie, setzt dabei ihre Samen frei und lässt oft auch Überreste ihrer Beute zurück.\"\nVerkaufspreis:" }
entries[89205] = { ["name"] = "Minimanabombe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Diese Minimanabombe werfen. (3 Min Abklingzeit)" }
