entries[89216] = { ["name"] = "Yis ungeliebter Helm", ["text"] = "Wird beim Aufheben gebunden\nKopf Platte\n12 Rüstung\n+1 [Stärke oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 2.\n\nMetasockel\nPrismatischer Sockel\nSockelbonus: + 10 Ausdauer\n\nHaltbarkeit 100 / 100\nVerkaufspreis:" }
entries[89222] = { ["name"] = "Wolkenring", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört einen Wolkenring, durch den Euer Haustier springt. Benötigt ein fliegendes Haustier. (10 Min Abklingzeit)\nBenötigt Orden der Wolkenschlange\n- Respektvoll\n\"Unterhaltung für Euer fliegendes Haustier.\"\nVerkaufspreis:" }
entries[89223] = { ["name"] = "Rennflagge", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Beschwört 15 Min. lang eine Rennflagge am Zielort. (30 Sek. Abklingzeit)\nBenötigt Orden der Wolkenschlange\n- Respektvoll\n\"Baut Eure eigene Rennstrecke.\"\nVerkaufspreis:" }
entries[89224] = { ["name"] = "Schwebende Rennflagge", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Beschwört 15 Min. lang eine schwebende Rennflagge an Eurem aktuellen Standort. Kann beim Reiten verwendet werden. (30 Sek. Abklingzeit)\nBenötigt Orden der Wolkenschlange\n- Respektvoll\n\"Baut Eure eigene Rennstrecke.\"\nVerkaufspreis:" }
entries[89225] = { ["name"] = "Ziellinie", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Beschwört 15 Min. lang eine Ziellinie am Zielort. (10 Min Abklingzeit)\nBenötigt Orden der Wolkenschlange\n- Respektvoll\n\"Baut Eure eigene Rennstrecke.\"\nVerkaufspreis:" }
entries[89227] = { ["name"] = "Schwebende Ziellinie", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Beschwört 15 Min. lang eine schwebende Ziellinie an Eurem aktuellen Standort. Kann beim Reiten verwendet werden. (10 Min Abklingzeit)\nBenötigt Orden der Wolkenschlange\n- Respektvoll\n\"Baut Eure eigene Rennstrecke.\"\nVerkaufspreis:" }
entries[89230] = { ["name"] = "Erneuernder Bern", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Schließt Euch selbst in erneuernden Bern ein. Stellt im Verlauf von 10 Sek. 4340 Gesundheit und ( 5203 / 5 * 10) Mana wieder her.\nBenötigt Die Klaxxi\n- Wohlwollend\nVerkaufspreis:" }
entries[89232] = { ["name"] = "Mogurune der Paralyse", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\nErhöht Eure Meisterschaftswertung um + 6.\nBenutzen: Platziert eine Mogurune der Paralyse auf dem Boden, die 1 Min. lang anhält und die nächste Kreatur 4 Sek. lang betäubt, die sie betritt. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[89233] = { ["name"] = "Klangglöckchensamen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Pflanzt Klangglöckchensamen.\nBenötigt einen respektvollen Ruf bei den Ackerbauern\n\"Die Harmonie der hellen und dunklen, glockenförmigen Blüten dieser Pflanze hat die pandarische Lied- und Dichtkunst über Jahrtausende hinweg beeinflusst.\"\nVerkaufspreis:" }
