entries[89362] = { ["name"] = "Zügel der braunen Reitziege", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört eine reitbare braune Reitziege und gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Die Ackerbauern\n- Ehrfürchtig\nBenötigt einen ehrfürchtigen Ruf bei den Ackerbauern\nVerkaufspreis:\n\"Man benötigt unerschütterliche Geduld und viel Feingefühl, um eine dickköpfige Bergziege aufs Reiten vorzubereiten.\"\nVerkäufer:\nGina Lehmkrall\nZone:\nTal der Vier Winde\nFraktion:\nDie Ackerbauern - Ehrfürchtig\nKosten:" }
entries[89363] = { ["name"] = "Scheibe der roten Flugwolke", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört eine rote Flugwolke oder gibt sie wieder frei. Dieses Fortbewegungsmittel passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Die Lehrensucher\n- Ehrfürchtig\nVerkaufspreis:\n\"Dieses uralte Moguartefakt wird jenen verliehen, die sich der Entdeckung und Weitergabe der Geschichte der Pandaren verschrieben haben.\"\nVerkäufer:\nTan Shin Tiao\nZone:\nTal der Ewigen Blüten\nFraktion:\nDie Lehrensucher - Ehrfürchtig\nKosten:" }
entries[89365] = { ["name"] = "Fieberbisseierbeutel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Öffnet Eier, lässt Fieberbissspinnen schlüpfen und sie 10 Min. lang auf Eure Gegner zuschwärmen. Kann nur im Freien verwendet werden. (30 Min Abklingzeit)\n3 Aufladungen\n\"Er zuckt...\"" }
