entries[89783] = { ["name"] = "Sattel des Sohnes von Galleon", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren Sohn von Galleon und gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Von jungem Alter an lernen diese riesigen Mushan, wie man mit einer ganzen Saurokkriegsmeute in die Schlacht stürmt.\"\nBeute von:\nGalleon\nOrt:\nTal der Vier Winde" }
